<?php if(!defined('ABSPATH'))exit;$plans=woogit_plans();get_header();?><section class="wg-section wg-pricing-page"><div class="wg-container"><div class="wg-section-head"><span class="wg-eyebrow">قیمت‌گذاری</span><h1>پلن مناسب WooGit را انتخاب کنید</h1><p>قیمت، ارز، دوره و دسترسی‌ها از منبع رسمی WooGit دریافت می‌شوند.</p></div><div class="wg-grid wg-grid--3"><?php if(!$plans): ?><div class="wg-card wg-empty" role="status"><h2>قیمت‌گذاری موقتاً در دسترس نیست.</h2><p>لطفاً بعداً دوباره تلاش کنید.</p></div><?php else: foreach($plans as $plan): if(!is_array($plan))continue;$id=(int)($plan['id']??$plan['plan_id']??0);$featured=!empty($plan['featured'])||!empty($plan['popular'])||!empty($plan['is_featured']);$trial=(int)($plan['trial_days']??0);$variations=array_values(array_filter((array)($plan['variations']??[]),'is_array'));$requires=!empty($plan['requires_variation'])||!empty($variations);$currency=woogit_safe_text($plan['currency']??'');$price=woogit_safe_text($plan['price']??'—');$webCheckoutUrl=esc_url((string)($plan['web_checkout_url']??''));?><article class="wg-plan<?php echo $featured?' wg-plan--featured':''; ?>" data-plan-card="<?php echo esc_attr($id); ?>"><?php if($featured): ?><span class="wg-plan__badge">پیشنهاد اصلی</span><?php endif; ?><h2><?php echo woogit_safe_text($plan['name']??'پلن'); ?></h2><div class="wg-price" data-woogit-price><?php echo $price; ?> <small><?php echo $currency; ?></small></div><?php if(!empty($plan['billing_period'])): ?><span class="wg-badge"><?php echo esc_html((int)($plan['billing_interval']??1)); ?> <?php echo woogit_safe_text($plan['billing_period']); ?></span><?php endif; ?><?php if($trial>0): ?><span class="wg-plan__trial"><?php echo esc_html($trial); ?> روز آزمایشی</span><?php endif; ?><p><?php echo woogit_safe_text($plan['description']??''); ?></p><?php if($variations): ?><label>نوع پلن<select data-woogit-variation-select data-plan-id="<?php echo esc_attr($id); ?>" aria-describedby="plan-<?php echo esc_attr($id); ?>-hint"><option value="">انتخاب کنید</option><?php foreach($variations as $v):$vid=(int)($v['id']??$v['variation_id']??0);if($vid<=0)continue;$vprice=woogit_safe_text($v['price']??$price);?><option value="<?php echo esc_attr($vid); ?>" data-price="<?php echo esc_attr($vprice); ?>" data-currency="<?php echo esc_attr(woogit_safe_text($v['currency']??$currency)); ?>"><?php echo woogit_safe_text($v['name']??$v['title']??$v['label']??'گزینه'); ?></option><?php endforeach; ?></select></label><p id="plan-<?php echo esc_attr($id); ?>-hint" class="wg-form-hint">ابتدا نوع پلن را انتخاب کنید.</p><?php endif; ?><button class="wg-btn" type="button" data-woogit-checkout data-plan-id="<?php echo esc_attr($id); ?>" data-variation-id="0"<?php echo $requires?' disabled':''; ?><?php echo $webCheckoutUrl?' data-web-checkout-url="'.$webCheckoutUrl.'"':''; ?>><?php echo $trial>0?'شروع آزمایشی':'ادامه به پرداخت'; ?></button><p class="wg-form-message" data-woogit-checkout-message aria-live="polite"></p></article><?php endforeach;endif; ?></div></div></section><?php get_footer(); ?>